import { AnchorHTMLAttributes, createContext } from 'react';
import type { RequireAtLeastOne } from 'type-fest';

import type {
  AriaButtonProps,
  ButtonAria,
} from '../../../buttons/button/types/button-aria.js';
import type { TimeframeV2 } from '../../../core/types/time.js';

export interface TimeframeSelectorContextProps {
  /** Current value of the timeframe selector */
  details: RequireAtLeastOne<TimeframeV2> | null;
  /** String displayed in the input field of the timeframe selector */
  displayValue: string;
  /** Necessary props for the trigger. */
  triggerProps:
    | (Partial<ButtonAria<AnchorHTMLAttributes<HTMLButtonElement>>> &
        AriaButtonProps)
    | null;
  /** Callback triggered whenever the value of the timeframe selector changes */
  onChange: (value: TimeframeV2 | null) => void;
}

/** Timeframe selector context, used to access the (input) value and onChange callback in other components. */
export const TimeframeSelectorContext: React.Context<TimeframeSelectorContextProps> =
  createContext<TimeframeSelectorContextProps>({
    details: null,
    displayValue: '',
    triggerProps: null,
    onChange: () => null,
  });
